const e="stearns-county-fair-amateur-talent-contest",u=2025,t="Built from the 2025 rules and registration form (image-only PDF, read from the page image). The registration deadline and the contest date are blank on the scan and are not captured. The contact e-mail address is not copied; the phone number is kept. The amount of the over-time point deduction is not printed. No fees, complaints procedure, ranks or points for places are printed.",n={Title:"Rules & Criteria",Subtitle:"Stearns County Fair Amateur Talent Contest: Pre-Teen, Teen and Open divisions, held on a Saturday at {{ContestVenue}}.",NoticeTitle:"Please Read Before Registering",Notice:"Pre-registration is required. Registration must be received by the deadline printed on the form. The contest begins at {{ContestStart}}.",Notes:["Sound equipment testing is from {{SoundTest}}."],Sections:[{Key:"general",Title:"General",Items:["The contest is sponsored by the Stearns County Fair.","The contest begins at {{ContestStart}} on a Saturday, at {{ContestVenue}}.","Sound equipment can be tested from {{SoundTest}}.","There is no lip sync.","Absolutely no vocals or background music will be allowed with instruments.","The fair provides a sound system. Contestants may use their own system.","All instruments, including keyboards, pianos and amplifiers, are the responsibility of the contestants."]},{Key:"eligibility",Title:"Who can enter",Items:["Pre-Teen Division: 12 years of age and under.","Teen Division: ages 13-18.","Open Division: any age.","Contestants must be residents of Stearns County.","Contestants must not be current-year winners in any other Minnesota county fair.","Each division needs a minimum of five contestants. A division with fewer is put into the Open division."]},{Key:"registration",Title:"How to enter",Items:["Pre-registration is required. Registration must be received by the deadline printed on the form.","Fill in the registration form: name, age, address, phone, parent's name (if under 18), division (Pre-Teen, Teen or Open), the selection to be performed, and whether you need the tape player or microphones.","Send the form by e-mail (address printed on the form) or mail it to {{MailTo}}.","For questions, contact {{ContestContact}}."]},{Key:"dates",Title:"Dates and times",Items:["The contest begins at {{ContestStart}} on Saturday.","Sound equipment testing is from {{SoundTest}}."]},{Key:"venue",Title:"Venue",Items:["The contest is held at {{ContestVenue}}."]},{Key:"judging",Title:"Judging",Items:["Contestants are judged on quality of performance, stage presence, entertainment value and selection.","There are three judges.","Judges' decisions are final.","Score sheets are not released to contestants or the public."]},{Key:"levels",Title:"State Fair",Items:["First-place winners in each division have the opportunity to compete at the State Fair."]},{Key:"prizes",Title:"Prizes",Items:["In each division the first, second and third place winners receive {{PrizeFirst}}, {{PrizeSecond}} and {{PrizeThird}}."]}],Documents:[{Title:"Talent Contest Rules and Registration Form (PDF)",Url:"https://stearnscountyfair.com/wp-content/uploads/2025/06/2025-Talent-Show-Entry-Form.pdf"}]},i=[],o=[],s=[{Title:"Talent Act",Source:"Time Limit and Equipment rules",Sections:{About:null,TimeAndFormat:["The time limit is four minutes. Points are deducted for contestants who go over the limit.","Musical groups and vocalists may perform a medley of tunes but must stay within the time limit."],Rules:null,Allowed:null,NotAllowed:["No lip sync.","No vocals or background music with instruments."],Judging:["Quality of performance, stage presence, entertainment value and selection, by three judges."],Points:null,Notes:null},Markdown:`## Time and format
- The time limit is four minutes. Points are deducted for contestants who go over the limit.
- Musical groups and vocalists may perform a medley of tunes but must stay within the time limit.

## Not allowed
- No lip sync.
- No vocals or background music with instruments.

## Judging
- Quality of performance, stage presence, entertainment value and selection, by three judges.`}],a=[],r=[{Key:"ContestStart",Kind:"time",Label:"Contest start",Value:"Noon, Saturday",Source:"Rules page, top"},{Key:"SoundTest",Kind:"time",Label:"Sound equipment testing",Value:"9:00 a.m. to 10:30 a.m.",Source:"Equipment rule"},{Key:"ContestVenue",Kind:"address",Label:"Contest venue",Value:{Name:"Heritage Stage, Stearns County Fair",Address:"",City:"",MapUrl:"",Directions:""},Source:"Rules page, top"},{Key:"MailTo",Kind:"address",Label:"Mail the form to",Value:{Name:"Stearns County Fair Amateur Talent Contest registration",Address:"120 6th St SE",City:"Sauk Centre, MN 56378",MapUrl:"",Directions:""},Source:"Registration form"},{Key:"ContestContact",Kind:"contact",Label:"Contact for questions",Value:{Name:"Abigail Olson",Role:"Contest contact",Phone:"320-429-1236",WhatsApp:"",Email:""},Source:"Registration form"},{Key:"PrizeFirst",Kind:"prize",Label:"First place prize",Value:"$100.00",Source:"Prizes box"},{Key:"PrizeSecond",Kind:"prize",Label:"Second place prize",Value:"$50.00",Source:"Prizes box"},{Key:"PrizeThird",Kind:"prize",Label:"Third place prize",Value:"$25.00",Source:"Prizes box"}],l=[{Claim:"Rules, eligibility, entry steps, times, prizes and judging are taken from the organiser's 2025 rules and registration form.",SourceType:"Primary - the event's own rules document",Source:"Stearns County Fair Amateur Talent Contest 2025 rules",Url:"https://stearnscountyfair.com/wp-content/uploads/2025/06/2025-Talent-Show-Entry-Form.pdf"}],d={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:i,AgeGroups:o,Competitions:s,CompetitionAgeGroups:a,Variables:r,Evidence:l};export{o as AgeGroups,a as CompetitionAgeGroups,s as Competitions,l as Evidence,t as Note,n as Page,i as ParticipantTypes,e as TemplateKey,r as Variables,u as Year,d as default};
